CONFIG = Path.home() / ".config/fbt-calibrator"
CAL_FILE = CONFIG / "calibration.json"
SETTINGS_FILE = CONFIG / "settings.json"
CACHE = Path.home() / ".cache/fbt-calibrator"
LOG_FILE = CONFIG / "fbt-calibrator.log"
SOCKET_NAME = "fbt-calibrator"
STATUS_FILE = CACHE / "status.json"  # read by the VRN (WayVR) watch panel
COMMANDS = CACHE / "commands"  # the watch panel drops one small file per button press here
SOUNDS = "/usr/share/sounds/freedesktop/stereo/"

def role_name(role):
    return tr(role) if role in B.ROLES else role


OVERRIDE_SECONDS = 30.0  # safety net; normally VRChat's "calibration ended" line releases it


def log(msg):
    CONFIG.mkdir(parents=True, exist_ok=True)
    line = time.strftime("%Y-%m-%d %H:%M:%S ") + msg
    print(line, flush=True)
    with open(LOG_FILE, "a") as f:
        f.write(line + "\n")


def play(name):
    subprocess.Popen(["paplay", SOUNDS + name], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def dot_image(color):
    CACHE.mkdir(parents=True, exist_ok=True)
    path = CACHE / f"dot-{color.lstrip('#')}.png"
    if not path.exists():
        img = QImage(64, 64, QImage.Format_ARGB32)
        img.fill(Qt.transparent)
        p = QPainter(img)
        p.setRenderHint(QPainter.Antialiasing)
        p.setBrush(QColor(color))
        p.setPen(QColor("white"))
        p.drawEllipse(4, 4, 56, 56)
        p.end()
        img.save(str(path))
    return str(path)


def load_json(path, default):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return default


def save_json(path, data):
    CONFIG.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=1, ensure_ascii=False))
    tmp.replace(path)


def pose_list(p):
    return [list(map(float, p[0])), list(map(float, p[1]))]


def pose_arr(lst):
    return np.array(lst[0]), np.array(lst[1])


class TPoseDetector:
    """Arms out at shoulder height, head level, held still ~1 s."""

    HOLD = 1.0

    def __init__(self):
        self.since = None
        self.anchor = None
        self.armed = True

    def update(self, head, left, right, now):
        if head is None or left is None or right is None:
            self.since = None
            return False
        eye = head[0][1]
        fwd, rvec = B.head_frame(head)
        look = B.q_rot(head[1], [0.0, 0.0, -1.0])
        arms_down = left[0][1] < eye - 0.6 and right[0][1] < eye - 0.6
        if arms_down:
            self.armed = True
        lx = np.dot(left[0] - head[0], rvec)
        rx = np.dot(right[0] - head[0], rvec)
        in_pose = (
            self.armed
            and abs(look[1]) < 0.35
            and eye - 0.45 < left[0][1] < eye + 0.1
            and eye - 0.45 < right[0][1] < eye + 0.1
            and lx < -0.45 and rx > 0.45
            and abs(np.dot(left[0] - head[0], fwd)) < 0.35
            and abs(np.dot(right[0] - head[0], fwd)) < 0.35
        )
        if not in_pose:
            self.since = None
            return False
        pts = np.concatenate([left[0], right[0], head[0]])
        if self.since is None or np.max(np.abs(pts - self.anchor)) > 0.05:
            self.since, self.anchor = now, pts
            return False
        if now - self.since >= self.HOLD:
            self.since = None
            self.armed = False  # lower the arms before the next one
            return True
        return False


class Calibrator:
    def __init__(self):
        self.shm = Shm()
        saved = load_json(CAL_FILE, {})
        self.eye = saved.get("eye_height")
        self.cal = {s: {"role": c["role"], "off": pose_arr(c["off"])}
                    for s, c in saved.get("trackers", {}).items()}
        self.settings = {"tpose": True, "dots": False, "stance_cm": 12, **load_json(SETTINGS_FILE, {})}
        self.vr = None
        self.overlay = None
        self.dots = {}
        self.dot_color = {}
        self.tpose = TPoseDetector()
        self.override_until = 0.0
        self.override = None
        self.status = {}
        self.last_vr_try = 0.0
        self.std_from_raw = None
        self.push_slots()

    # ---- shared memory ----
    def push_slots(self):
        slots = []
        for serial, c in self.cal.items():
            s = {"serial": serial, "mode": OFFSET, "off": c["off"]}
            if self.override and serial in self.override:
                s["mode"] = OVERRIDE
                s["ov"] = self.override[serial]
            slots.append(s)
        self.shm.write_slots(slots)

    def save(self):
        save_json(CAL_FILE, {
            "eye_height": self.eye,
            "trackers": {s: {"role": c["role"], "off": pose_list(c["off"])} for s, c in self.cal.items()},
        })

    # ---- SteamVR ----
    def ensure_vr(self):
        if self.vr:
            return True
        if time.monotonic() - self.last_vr_try < 3:
            return False
        self.last_vr_try = time.monotonic()
        # openvr.init() starts SteamVR when it is not running; after a SteamVR crash that
        # turned into a restart loop (2026-10-20). Only attach to an already-running vrserver.
        if subprocess.run(["pgrep", "-x", "vrserver"], stdout=subprocess.DEVNULL).returncode != 0:
            return False
        try:
            self.vr = openvr.init(openvr.VRApplication_Overlay)
            self.overlay = openvr.IVROverlay()
            log("connected to SteamVR")
            return True
        except openvr.OpenVRError:
            self.vr = None
            return False

    def drop_vr(self):
        for h in self.dots.values():
            try:
                self.overlay.destroyOverlay(h)
            except openvr.OpenVRError:
                pass
        self.dots = {}
        self.dot_color = {}
        try:
            openvr.shutdown()
        except openvr.OpenVRError:
            pass
        self.vr = None
        self.std_from_raw = None
        self.last_vr_try = time.monotonic() + 10  # let a quitting vrserver exit first
        log("SteamVR closed")

    def tick(self):
        self.shm.heartbeat()
        if not self.ensure_vr():
            return
        ev = openvr.VREvent_t()
        while self.vr.pollNextEvent(ev):
            if ev.eventType == openvr.VREvent_Quit:
                self.vr.acknowledgeQuit_Exiting()
                self.drop_vr()
                return

        n = openvr.k_unMaxTrackedDeviceCount
        std = self.vr.getDeviceToAbsoluteTrackingPose(openvr.TrackingUniverseStanding, 0, n)
        raw = self.vr.getDeviceToAbsoluteTrackingPose(openvr.TrackingUniverseRawAndUncalibrated, 0, n)
        if not std[0].bPoseIsValid:
            return
        head = B.mat_to_pose(std[0].mDeviceToAbsoluteTracking.m)
        head_raw = B.mat_to_pose(raw[0].mDeviceToAbsoluteTracking.m)
        self.std_from_raw = B.compose(head, B.inverse(head_raw))

        left = right = None
        trackers_real, final = {}, {}
        for i in range(1, n):
            cls = self.vr.getTrackedDeviceClass(i)
            if cls == openvr.TrackedDeviceClass_Controller and std[i].bPoseIsValid:
                role = self.vr.getControllerRoleForTrackedDeviceIndex(i)
                p = B.mat_to_pose(std[i].mDeviceToAbsoluteTracking.m)
                if role == openvr.TrackedControllerRole_LeftHand:
                    left = p
                elif role == openvr.TrackedControllerRole_RightHand:
                    right = p
            elif cls == openvr.TrackedDeviceClass_GenericTracker:
                serial = self.vr.getStringTrackedDeviceProperty(i, openvr.Prop_SerialNumber_String)
                rp = self.shm.raw_pose(i)
                if rp is not None:
                    trackers_real[serial] = B.compose(self.std_from_raw, rp)
                if std[i].bPoseIsValid:
                    final[serial] = B.mat_to_pose(std[i].mDeviceToAbsoluteTracking.m)
        self.status = {"driver": self.shm.driver_alive(), "seen": set(trackers_real), "final": final}

        now = time.monotonic()
        if self.override and now > self.override_until:
            self.end_override()
        elif self.override:
            self.follow_head(head)
        if self.settings["tpose"] and not self.override and self.tpose.update(head, left, right, now):
            self.calibrate(head, trackers_real)
        self.update_dots(head, final)

    # ---- actions ----
    def calibrate(self, head, trackers_real):
        cal, eye = B.calibrate(head, trackers_real)
        if not cal:
            log(f"T-pose seen but only {len(trackers_real)} trackers are tracking")
            play("dialog-warning.oga")
            return
        roles = {s: c["role"] for s, c in cal.items()}
        if not B.feet_together(trackers_real, roles):
            log("T-pose seen but feet are not together — skipped")
            play("dialog-warning.oga")
            return
        self.cal, self.eye = cal, eye
        self.save()
        self.push_slots()
        play("camera-shutter.oga")
        log("calibrated: eye %.3f m, %s" % (eye, roles))

    def start_override(self, reason):
        if self.override and reason.startswith("VRChat"):
            return  # both VRChat start lines arrive for one calibration
        if not self.cal or self.eye is None or not self.vr or self.std_from_raw is None:
            log("VRChat calibration requested but not calibrated / no SteamVR")
            play("dialog-warning.oga")
            return
        poses = self.vr.getDeviceToAbsoluteTrackingPose(openvr.TrackingUniverseStanding, 0, 1)
        head = B.mat_to_pose(poses[0].mDeviceToAbsoluteTracking.m)
        self.settings.update(load_json(SETTINGS_FILE, {}))  # may be edited outside the window
        self.override_until = time.monotonic() + OVERRIDE_SECONDS
        self.follow_head(head)
        play("bell.oga")
        log(f"trackers frozen on ideal T-pose ({reason})")

    def follow_head(self, head):
        """Put the frozen trackers on the ideal T-pose under the current head.

        Called every tick while frozen: VRChat keeps hanging the avatar from the head until
        the trigger is pulled, so the trackers stay "magnetised" to it when she turns or nods.
        """
        side = self.settings["stance_cm"] / 200.0
        model = B.model_points(head, self.eye, head_y=B.level_eye_y(head), ankle_side=side)
        raw_from_std = B.inverse(self.std_from_raw)
        self.override = {s: B.compose(raw_from_std, model[c["role"]]) for s, c in self.cal.items()}
        self.push_slots()

    def end_override(self):
        if self.override:
            self.override = None
            self.push_slots()
            play("complete.oga")
            log("trackers follow the body again")

    def reset(self):
        self.cal, self.eye = {}, None
        self.save()
        self.shm.write_slots([])
        log("calibration cleared")

    def write_status(self):
        """Snapshot for the watch panel in VRN; a stale timestamp tells it we are not running."""
        seen = self.status.get("seen", set())
        trackers = [{"role": role_name(i["role"]), "ok": serial in seen}
                    for serial, i in sorted(self.cal.items(), key=lambda kv: kv[1]["role"])]
        data = {
            "ts": time.time(),
            "vr": bool(self.vr),
            "driver": bool(self.status.get("driver")),
            "calibrated": bool(self.cal),
            "trackers": trackers,
            "override_left": max(0, int(self.override_until - time.monotonic())) if self.override else None,
            "tpose": bool(self.settings["tpose"]),
            "dots": bool(self.settings["dots"]),
            "stance_cm": int(self.settings["stance_cm"]),
        }
        CACHE.mkdir(parents=True, exist_ok=True)
        tmp = STATUS_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(data, ensure_ascii=False))
        tmp.replace(STATUS_FILE)

    def update_dots(self, head, final):
        if not self.settings["dots"]:
            for h in self.dots.values():
                self.overlay.hideOverlay(h)
            return
        for serial, c in self.cal.items():
            h = self.dots.get(serial)
            if h is None:
                h = self.overlay.createOverlay(f"fbtcal.dot.{serial}", f"fbtcal {serial}")
                self.overlay.setOverlayWidthInMeters(h, 0.06)
                self.dots[serial] = h
            p = final.get(serial)
            if p is None:
                self.overlay.hideOverlay(h)
                continue
            color = "#f5a623" if self.override else "#3d8bfd"
            if self.dot_color.get(serial) != color:
                # Upload the texture only when it changes: re-uploading it every frame
                # crashed vrcompositor (VkResult UNKNOWN_ERROR) on 2026-10-20.
                self.overlay.setOverlayFromFile(h, dot_image(color))
                self.dot_color[serial] = color
            z = head[0] - p[0]
            z /= np.linalg.norm(z) + 1e-9
            x = np.cross(B.UP, z)
            x /= np.linalg.norm(x) + 1e-9
            y = np.cross(z, x)
            m = openvr.HmdMatrix34_t()
            for r in range(3):
                m.m[r][0], m.m[r][1], m.m[r][2], m.m[r][3] = x[r], y[r], z[r], p[0][r]
            self.overlay.setOverlayTransformAbsolute(h, openvr.TrackingUniverseStanding, m)
            self.overlay.showOverlay(h)


class Window(QWidget):
    def __init__(self, cal):
        super().__init__()
        self.cal = cal
        self.setWindowTitle(tr("title"))
        lay = QVBoxLayout(self)
        self.info = QLabel()
        self.info.setWordWrap(True)
        lay.addWidget(self.info)

        btn = QPushButton(tr("btn_override"))
        btn.clicked.connect(lambda: cal.start_override("button"))
        lay.addWidget(btn)

        self.tpose = QCheckBox(tr("chk_tpose"))
        self.tpose.setChecked(cal.settings["tpose"])
        self.tpose.toggled.connect(lambda v: self.set("tpose", v))
        lay.addWidget(self.tpose)

        self.dots = QCheckBox(tr("chk_dots"))
        self.dots.setChecked(cal.settings["dots"])
        self.dots.toggled.connect(lambda v: self.set("dots", v))
        lay.addWidget(self.dots)

        row = QHBoxLayout()
        narrower = QPushButton(tr("narrower"))
        narrower.clicked.connect(lambda: self.stance(-2))
        wider = QPushButton(tr("wider"))
        wider.clicked.connect(lambda: self.stance(+2))
        self.stance_label = QLabel()
        row.addWidget(narrower)
        row.addWidget(self.stance_label)
        row.addWidget(wider)
        lay.addLayout(row)
        self.stance(0)

        reset = QPushButton(tr("reset"))
        reset.clicked.connect(cal.reset)
        lay.addWidget(reset)

        upd = QPushButton(tr("update"))
        upd.clicked.connect(self.check_update)
        lay.addWidget(upd)

        about = QLabel(tr("about", v=VERSION, repo=REPO))
        about.setOpenExternalLinks(True)
        about.setStyleSheet("color: gray; font-size: small")
        lay.addWidget(about)
        self.resize(400, 300)

    def check_update(self):
        try:
            info = update.check()
            if not info:
                QMessageBox.information(self, tr("title"), tr("update_none", v=VERSION))
                return
            if QMessageBox.question(self, tr("title"), tr("update_ask", v=info["version"])) != QMessageBox.Yes:
                return
            update.install(info)
        except Exception as e:  # network, GitHub or installer failure: tell the user, keep running
            QMessageBox.warning(self, tr("title"), tr("update_fail", e=e))
            return
        QMessageBox.information(self, tr("title"), tr("update_done", v=info["version"]))
        log(f"updated to {info['version']}, restarting")
        subprocess.Popen(["bash", "-c", "sleep 2; exec \"$0\"", str(Path.home() / ".local/bin/fbt-calibrator")],
                         start_new_session=True)
        QApplication.quit()

    def stance(self, delta):
        """Feet distance used for VRChat calibration (applies on the next one)."""
        cm = max(0, min(40, self.cal.settings["stance_cm"] + delta))
        self.set("stance_cm", cm)
        self.stance_label.setText(tr("stance", cm=cm))

    def set(self, key, value):
        self.cal.settings[key] = value
        save_json(SETTINGS_FILE, self.cal.settings)

    def refresh(self):
        c = self.cal
        lines = []
        if not c.vr:
            lines.append(tr("wait_vr"))
        elif not c.status.get("driver"):
            lines.append(tr("no_driver"))
        if not c.cal:
            lines.append(tr("not_calibrated"))
        else:
            seen = c.status.get("seen", set())
            for serial, info in sorted(c.cal.items(), key=lambda kv: kv[1]["role"]):
                ok = "✅" if serial in seen else "❌"
                lines.append(f"{ok} {role_name(info['role'])}")
        if c.override:
            left = max(0, int(c.override_until - time.monotonic()))
            lines.append(tr("frozen", s=left))
        self.info.setText("\n".join(lines))


def handle_watch_commands(cal, win):
    """Button presses from the VRN watch panel: one file per command in COMMANDS."""
    if not COMMANDS.is_dir():
        return
    for path in sorted(COMMANDS.iterdir()):
        try:
            cmd = path.read_text().split()
            path.unlink()
        except OSError:
            continue
        log(f"watch command: {' '.join(cmd)}")
        if cmd[:1] == ["override"]:
            cal.start_override("watch")
        elif cmd[:1] == ["reset"]:
            cal.reset()
        elif cmd[:2] == ["toggle", "tpose"]:
            win.tpose.setChecked(not win.tpose.isChecked())
        elif cmd[:2] == ["toggle", "dots"]:
            win.dots.setChecked(not win.dots.isChecked())
        elif cmd[:1] == ["stance"] and len(cmd) == 2 and cmd[1].lstrip("+-").isdigit():
            win.stance(int(cmd[1]))
        elif cmd[:1] == ["show"]:
            bring_up(win)


def single_instance():
    import ctypes
    import fcntl
    ctypes.CDLL(None).prctl(15, b"fbt-calibrator", 0, 0, 0)  # PR_SET_NAME, so launchers can see us
    CONFIG.mkdir(parents=True, exist_ok=True)
    lock = open(CONFIG / ".lock", "w")
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        # Already running: ask that instance to show its window (the menu shortcut uses --show).
        from PySide6.QtNetwork import QLocalSocket
        sock = QLocalSocket()
        sock.connectToServer(SOCKET_NAME)
        if sock.waitForConnected(1000):
            sock.write(b"show")
            sock.waitForBytesWritten(1000)
        print("already running")
        sys.exit(0)
    return lock


def listen_for_show(win):
    from PySide6.QtNetwork import QLocalServer
    QLocalServer.removeServer(SOCKET_NAME)
    server = QLocalServer()
    server.listen(SOCKET_NAME)

    def on_conn():
        conn = server.nextPendingConnection()
        conn.readyRead.connect(lambda: (conn.readAll(), bring_up(win)))
    server.newConnection.connect(on_conn)
    return server


def bring_up(win):
    win.show()
    win.setWindowState(win.windowState() & ~Qt.WindowMinimized)
    win.raise_()
    win.activateWindow()


def main():
    lock = single_instance()  # noqa: F841 — held for the process lifetime
    app = QApplication(sys.argv)
    app.setQuitOnLastWindowClosed(False)
    cal = Calibrator()
    win = Window(cal)

    watcher = VrchatLogWatcher(on_start=lambda: cal.start_override("VRChat calibration"),
                               on_end=cal.end_override, log=log)

    pix = QPixmap(dot_image("#3d8bfd"))
    tray = QSystemTrayIcon(QIcon(pix))
    tray.setToolTip(tr("title"))
    menu = QMenu()
    show = QAction(tr("tray_open"), menu)
    show.triggered.connect(lambda: bring_up(win))
    menu.addAction(show)
    vrc = QAction(tr("btn_override"), menu)
    vrc.triggered.connect(lambda: cal.start_override("tray"))
    menu.addAction(vrc)
    quit_ = QAction(tr("tray_quit"), menu)
    quit_.triggered.connect(app.quit)
    menu.addAction(quit_)
    tray.setContextMenu(menu)
    tray.activated.connect(lambda r: bring_up(win) if r == QSystemTrayIcon.Trigger else None)
    tray.show()
    server = listen_for_show(win)  # noqa: F841 — keep alive
    if "--show" in sys.argv:
        bring_up(win)

    timer = QTimer()
    timer.setTimerType(Qt.PreciseTimer)

    def tick():
        try:
            cal.tick()
        except openvr.OpenVRError as e:
            log(f"OpenVR error: {e}")
            cal.drop_vr()
    timer.timeout.connect(tick)
    timer.start(11)

    slow = QTimer()
    slow.timeout.connect(lambda: (win.refresh(), watcher.poll(), handle_watch_commands(cal, win), cal.write_status()))
    slow.start(250)

    log("started")
    code = app.exec()
    if cal.vr:
        cal.drop_vr()
    sys.exit(code)


if __name__ == "__main__":
    main()
